from __future__ import annotations

import os
import re
import threading
import time
from pathlib import Path
from typing import Any, Callable, Iterable
from urllib.parse import urlparse

from .models_catalog import PROFILES, SHIPPED_WITH_APP, get_catalog, get_spec
from .paths import get_models_root

ProgressCb = Callable[[dict[str, Any]], None]

DEFAULT_HF_MIRROR = "https://hf-mirror.com"
# huggingface_hub defaults to 10s which is too aggressive for domestic mirrors / CDN hops.
DEFAULT_HF_DOWNLOAD_TIMEOUT = 120
DEFAULT_HF_ETAG_TIMEOUT = 30
# Extra attempts after a connectivity failure (Range resume is handled inside huggingface_hub).
CONNECTIVITY_RETRY_ATTEMPTS = 3
_URL_IN_TEXT_RE = re.compile(r"https?://[^\s\"'<>\\\]]+", re.IGNORECASE)


def model_local_path(spec_id: str) -> Path:
    spec = get_spec(spec_id)
    if not spec:
        raise KeyError(f"unknown model: {spec_id}")
    return get_models_root() / spec.kind / spec.local_dirname


def _weight_markers_for(spec) -> tuple[str, ...]:
    kind = getattr(spec, "kind", "") or ""
    backend = getattr(spec, "backend", "") or ""
    if kind == "mt" or backend in ("opus-ct2", "marian"):
        return ("pytorch_model.bin", "model.safetensors", "model.bin", "tf_model.h5")
    if backend == "whisperseg" or str(getattr(spec, "id", "")) == "whisperseg-asmr":
        return ("model.onnx",)
    if backend == "reazon-k2":
        return (
            "encoder-epoch-99-avg-1.onnx",
            "encoder-epoch-99-avg-1.int8.onnx",
            "tokens.txt",
        )
    if backend in ("qwen3-asr", "qwen3-align"):
        return (
            "model.safetensors",
            "model.safetensors.index.json",
            "pytorch_model.bin",
            "config.json",
        )
    if "whisper" in backend or "whisper" in str(getattr(spec, "id", "")):
        return ("model.bin",)
    # SenseVoice / FunASR VAD / default ASR
    return ("model.pt", "model.bin")


def is_model_installed(spec_id: str) -> bool:
    spec = get_spec(spec_id)
    # Empty hub_id means bundled runtime dependency (no separate download).
    if spec is not None and not str(spec.hub_id or "").strip():
        return True
    path = model_local_path(spec_id)
    if not path.exists() or not path.is_dir():
        return False
    markers = _weight_markers_for(spec) if spec else ("model.pt", "model.bin", "pytorch_model.bin")
    for name in markers:
        candidate = path / name
        try:
            if not candidate.exists():
                continue
            # tokens.txt / small config markers may be under 1KB
            min_size = 64 if name.lower().endswith((".txt", ".json")) else 1024
            if candidate.stat().st_size > min_size:
                return True
        except OSError:
            continue
    return False


def _dir_has_meaningful_content(local: Path) -> bool:
    """True when local dir has files beyond Hub cache / dotfiles (partial download residue)."""
    if not local.exists() or not local.is_dir():
        return False
    try:
        for p in local.iterdir():
            name = p.name
            if name.startswith(".") or name in ("README.md",):
                continue
            return True
    except OSError:
        return False
    return False


def _hub_ignore_patterns_for(spec) -> list[str] | None:
    """Skip unused framework dumps so Opus MT pulls stay small and finish reliably."""
    kind = getattr(spec, "kind", "") or ""
    backend = getattr(spec, "backend", "") or ""
    if kind == "mt" or backend in ("opus-ct2", "marian"):
        return [
            "flax_model*",
            "rust_model*",
            "tf_model*",
            "*.msgpack",
            "*.ot",
            "*.h5",
            "onnx/*",
            "*.onnx",
        ]
    return None


def list_models_status() -> list[dict[str, Any]]:
    out = []
    for spec in get_catalog():
        item = spec.to_dict()
        installed = is_model_installed(spec.id)
        item["installed"] = installed
        item["path"] = str(model_local_path(spec.id))
        shipped = spec.id in SHIPPED_WITH_APP
        item["shipped"] = shipped
        # Empty hub_id = runtime-builtin (silero). Shipped models report bundled only when present on disk.
        item["bundled"] = (not str(spec.hub_id or "").strip()) or (shipped and installed)
        if not installed:
            local = model_local_path(spec.id)
            item["incomplete"] = _dir_has_meaningful_content(local)
        else:
            item["incomplete"] = False
        out.append(item)
    return out


def resolve_download_ids(profile: str | None, model_ids: Iterable[str] | None) -> list[str]:
    ids: list[str] = []
    if model_ids:
        ids.extend([str(x).strip() for x in model_ids if str(x).strip()])
    if profile:
        p = PROFILES.get(str(profile).strip())
        if not p:
            raise KeyError(f"unknown profile: {profile}")
        ids.extend(
            [
                p["asrModel"],
                p["mtModelEnZh"],
                p["mtModelJaZh"],
                p.get("mtModelKoZh") or "opus-mt-ko-zh",
                p["vadModel"],
            ]
        )
    # stable unique
    seen: set[str] = set()
    ordered: list[str] = []
    for mid in ids:
        if mid not in seen:
            seen.add(mid)
            ordered.append(mid)
    if not ordered:
        raise ValueError("provide profile or modelIds")
    return ordered


def _apply_hf_hub_timeouts() -> None:
    """Raise Hub HTTP timeouts and sync already-imported huggingface_hub.constants."""
    os.environ.setdefault("HF_HUB_DOWNLOAD_TIMEOUT", str(DEFAULT_HF_DOWNLOAD_TIMEOUT))
    os.environ.setdefault("HF_HUB_ETAG_TIMEOUT", str(DEFAULT_HF_ETAG_TIMEOUT))
    # hf-mirror + Xet/CAS frequently 401s for large LFS files; prefer classic transfer.
    os.environ.setdefault("HF_HUB_DISABLE_XET", "1")
    try:
        import huggingface_hub.constants as hf_constants

        download_timeout = int(os.environ.get("HF_HUB_DOWNLOAD_TIMEOUT") or DEFAULT_HF_DOWNLOAD_TIMEOUT)
        etag_timeout = int(os.environ.get("HF_HUB_ETAG_TIMEOUT") or DEFAULT_HF_ETAG_TIMEOUT)
        hf_constants.HF_HUB_DOWNLOAD_TIMEOUT = max(1, download_timeout)
        hf_constants.HF_HUB_ETAG_TIMEOUT = max(1, etag_timeout)
    except Exception:
        pass


def apply_hf_endpoint(endpoint: str | None = None) -> str:
    """
    Apply Hugging Face Hub endpoint for this process.
    Empty string clears override (falls back to env / official hub).
    """
    _apply_hf_hub_timeouts()
    raw = endpoint if endpoint is not None else os.environ.get("HF_ENDPOINT", "")
    ep = str(raw or "").strip().rstrip("/")
    if ep:
        os.environ["HF_ENDPOINT"] = ep
        try:
            import huggingface_hub.constants as hf_constants

            hf_constants.ENDPOINT = ep
        except Exception:
            pass
    return ep


def _is_hub_connectivity_error(err: BaseException | str) -> bool:
    msg = str(err or "")
    lowered = msg.lower()
    return (
        "connecttimeout" in lowered
        or "connecterror" in lowered
        or "10060" in msg
        or "10054" in msg  # connection reset by peer (common on blocked HF)
        or "timed out" in lowered
        or "timeout" in lowered
        or "connection attempt failed" in lowered
        or "failed to establish a new connection" in lowered
        or "connection reset" in lowered
        or "forcibly closed" in lowered
        or "remoteprotocolerror" in lowered
        or "server disconnected" in lowered
        or "远程主机强迫关闭" in msg
        or "name or service not known" in lowered
        or "nodename nor servname" in lowered
        or (
            "cannot find the appropriate snapshot folder" in lowered
            and ("connect" in lowered or "internet connection" in lowered)
        )
    )


def _endpoint_is_mirror(endpoint: str) -> bool:
    host = (urlparse((endpoint or "").strip() or "https://huggingface.co").hostname or "").lower()
    return host == "hf-mirror.com" or host.endswith(".hf-mirror.com")


def _extract_urls_from_text(text: str) -> list[str]:
    found: list[str] = []
    seen: set[str] = set()
    for match in _URL_IN_TEXT_RE.findall(str(text or "")):
        cleaned = match.rstrip(").,;]")
        if cleaned in seen:
            continue
        seen.add(cleaned)
        found.append(cleaned)
    return found


def _probe_resolve_redirect(url: str, *, timeout: float = 8.0) -> dict[str, Any] | None:
    """Follow redirects for a resolve URL; return final host (often a CDN)."""
    try:
        import httpx
    except Exception:
        return None
    try:
        limits = httpx.Timeout(timeout, connect=min(5.0, timeout))
        with httpx.Client(follow_redirects=True, timeout=limits) as client:
            try:
                res = client.head(url)
                if res.status_code in (405, 501):
                    res = client.get(url)
            except Exception:
                res = client.get(url)
        final_url = str(res.url)
        host = urlparse(final_url).hostname or ""
        return {
            "ok": 200 <= res.status_code < 500,
            "status": res.status_code,
            "final_url": final_url,
            "host": host,
        }
    except Exception as probe_err:
        return {"ok": False, "error": str(probe_err)}


def _diagnose_hub_connectivity(*, hub_id: str, endpoint: str, err: BaseException | str) -> str:
    """Build a short diagnostic about mirror vs CDN redirect targets.

    Best-effort only: never block the failure path for long on a dead network.
    Prefer URLs already present in the Hub error (actual file resolve / CDN hop).
    """
    using = (endpoint or "https://huggingface.co").rstrip("/")
    urls = _extract_urls_from_text(str(err))
    # Only probe when the error already exposed a concrete download URL; otherwise
    # a synthetic config.json HEAD against a blocked hub can hang the UI error path.
    if not urls:
        return ""
    probe_url = urls[0]
    probe = _probe_resolve_redirect(probe_url, timeout=6.0)
    if not probe:
        return ""
    if probe.get("error"):
        return f"探测下载链接失败: {str(probe['error'])[:160]}"
    final_host = str(probe.get("host") or "")
    ep_host = (urlparse(using).hostname or "").lower()
    if final_host and final_host.lower() != ep_host and "hf-mirror" not in final_host.lower():
        return (
            f"文件实际跳转到 {final_host}（非镜像站本身），"
            f"该 CDN/对象存储链路可能被重置或超时"
        )
    if final_host:
        return f"探测终点主机 {final_host}（HTTP {probe.get('status')}）"
    return ""


def format_hub_download_error(
    err: BaseException,
    *,
    model_id: str,
    endpoint: str,
    hub_id: str | None = None,
) -> str:
    msg = str(err)
    lowered = msg.lower()
    if _is_hub_connectivity_error(err):
        hint_ep = DEFAULT_HF_MIRROR
        using = (endpoint or "https://huggingface.co").rstrip("/")
        on_mirror = _endpoint_is_mirror(using)
        diag = ""
        if hub_id:
            try:
                diag = _diagnose_hub_connectivity(hub_id=hub_id, endpoint=using, err=err)
            except Exception:
                diag = ""
        diag_suffix = f" {diag}。" if diag else ""
        if on_mirror:
            return (
                f"无法连接模型仓库以下载 {model_id}（连接被重置/超时）。"
                f"当前已使用镜像 {using}。"
                f"浏览器能打开镜像站不代表软件内下载链路可用（引擎使用 Python httpx）。"
                f"请尝试：①切换或关闭「设置→网络」代理后重试；②稍后重试；"
                f"③确认系统时间正确。{diag_suffix}"
                f" 详情: {msg}"
            )
        return (
            f"无法连接模型仓库以下载 {model_id}（网络中断/超时）。"
            f"当前端点为 {using}；国内网络请将 Hugging Face 镜像设为 {hint_ep} 后重试。"
            f"{diag_suffix}"
            f" 详情: {msg}"
        )
    if "repository not found" in lowered or ("401" in msg and "repo" in lowered):
        return (
            f"下载 {model_id} 失败：Hub 仓库不存在或不可访问。"
            f"请升级引擎目录后重试（或检查模型 catalog 中的 hub_id）。"
            f" 详情: {msg}"
        )
    return f"下载 {model_id} 失败: {msg}"


def _dir_nbytes(path: Path) -> int:
    total = 0
    try:
        if not path.exists():
            return 0
        for root, _dirs, files in os.walk(path):
            for name in files:
                try:
                    total += (Path(root) / name).stat().st_size
                except OSError:
                    continue
    except OSError:
        return total
    return total


def _size_hint_bytes(spec) -> int:
    try:
        mb = int(getattr(spec, "size_hint_mb", 0) or 0)
    except (TypeError, ValueError):
        mb = 0
    return max(0, mb) * 1024 * 1024


class _DirSizeWatcher:
    """Poll destination folder size while Hugging Face download runs."""

    def __init__(
        self,
        dest: Path,
        emit: ProgressCb,
        *,
        model_id: str,
        index: int,
        model_count: int,
        size_hint_bytes: int,
        endpoint: str,
    ) -> None:
        self.dest = dest
        self.emit = emit
        self.model_id = model_id
        self.index = index
        self.model_count = model_count
        self.size_hint_bytes = max(0, int(size_hint_bytes or 0))
        self.endpoint = endpoint
        self._stop = threading.Event()
        self._thread: threading.Thread | None = None
        self._last_bytes = 0
        self._last_t = time.monotonic()
        self._speed = 0.0

    def start(self) -> None:
        self._thread = threading.Thread(target=self._run, name=f"dl-watch-{self.model_id}", daemon=True)
        self._thread.start()

    def stop(self) -> None:
        self._stop.set()
        if self._thread and self._thread.is_alive():
            self._thread.join(timeout=1.5)

    def _run(self) -> None:
        while not self._stop.wait(0.4):
            self._tick()

    def _tick(self) -> None:
        cur = _dir_nbytes(self.dest)
        now = time.monotonic()
        dt = max(1e-3, now - self._last_t)
        if cur >= self._last_bytes:
            self._speed = (cur - self._last_bytes) / dt
        self._last_bytes = cur
        self._last_t = now
        # Stable size hint for UI; do not raise total to match cur (avoids "X / X").
        total_b = self.size_hint_bytes
        local_frac = min(0.99, (cur / total_b)) if total_b > 0 else 0.0
        overall = int(100 * (self.index + local_frac) / max(self.model_count, 1))
        payload: dict[str, Any] = {
            "type": "progress",
            "stage": "download",
            "modelId": self.model_id,
            "index": self.index + 1,
            "total": self.model_count,
            "percent": min(99, max(0, overall)),
            "downloadedBytes": cur,
            "bytesPerSecond": round(self._speed, 1),
            "detail": f"正在下载 {self.model_id}…",
            "endpoint": self.endpoint or "https://huggingface.co",
        }
        if total_b > 0:
            payload["totalBytes"] = total_b
        try:
            self.emit(payload)
        except Exception:
            pass


def download_models(
    *,
    profile: str | None = None,
    model_ids: list[str] | None = None,
    hf_endpoint: str | None = None,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    ids = resolve_download_ids(profile, model_ids)
    try:
        from .models_catalog import expand_model_companions

        ids = expand_model_companions(ids)
    except Exception:
        pass
    results: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    endpoint = apply_hf_endpoint(hf_endpoint)

    def emit(payload: dict[str, Any]) -> None:
        if on_progress:
            on_progress(payload)

    # Dist ships HTTP-min deps only; install ASR/MT/VAD wheels before Hub weights.
    try:
        from .runtime_extras import ensure_extras_for_models

        emit(
            {
                "type": "progress",
                "stage": "pip",
                "detail": "正在检查并安装推理依赖（faster-whisper / numpy 等）…",
                "percent": 0,
            }
        )
        extras_res = ensure_extras_for_models(ids, force=bool(force), on_progress=emit)
        if not extras_res.get("ok"):
            msg = str(extras_res.get("message") or "安装推理依赖失败")
            emit({"type": "error", "code": extras_res.get("code") or "EXTRAS_INSTALL_FAILED", "message": msg})
            raise RuntimeError(msg)
    except ImportError:
        pass

    total = len(ids)
    for index, mid in enumerate(ids):
        spec = get_spec(mid)
        if not spec:
            emit({"type": "error", "code": "UNKNOWN_MODEL", "message": f"unknown model: {mid}"})
            raise KeyError(mid)
        dest = model_local_path(mid)
        dest.parent.mkdir(parents=True, exist_ok=True)
        hint_bytes = _size_hint_bytes(spec)
        emit(
            {
                "type": "progress",
                "stage": "download",
                "modelId": mid,
                "index": index + 1,
                "total": total,
                "percent": int(100 * index / max(total, 1)),
                "downloadedBytes": 0,
                "totalBytes": hint_bytes or None,
                "bytesPerSecond": 0,
                "detail": f"正在下载 {mid}…",
                "endpoint": endpoint or "https://huggingface.co",
            }
        )
        try:
            # Bundled models (empty hub_id) need no Hub fetch.
            if not str(spec.hub_id or "").strip():
                results.append({"id": mid, "ok": True, "path": str(dest), "bundled": True})
                emit(
                    {
                        "type": "progress",
                        "stage": "download",
                        "modelId": mid,
                        "index": index + 1,
                        "total": total,
                        "percent": int(100 * (index + 1) / max(total, 1)),
                        "detail": f"内置模型 {mid}（无需下载）",
                    }
                )
                continue

            from huggingface_hub import snapshot_download
            import shutil

            # Skip re-download when already installed (idempotent retries).
            if not force and is_model_installed(mid):
                results.append({"id": mid, "ok": True, "path": str(dest), "skipped": True})
                emit(
                    {
                        "type": "progress",
                        "stage": "download",
                        "modelId": mid,
                        "index": index + 1,
                        "total": total,
                        "percent": int(100 * (index + 1) / max(total, 1)),
                        "detail": f"已安装 {mid}",
                    }
                )
                continue

            # Force reinstall: wipe local dir. Otherwise keep incomplete files so Hub can Range-resume.
            if force and dest.exists():
                emit(
                    {
                        "type": "progress",
                        "stage": "download",
                        "modelId": mid,
                        "index": index + 1,
                        "total": total,
                        "percent": int(100 * index / max(total, 1)),
                        "detail": f"强制重新下载 {mid}…",
                    }
                )
                shutil.rmtree(dest, ignore_errors=True)
            dest.mkdir(parents=True, exist_ok=True)

            def _run_snapshot(active_endpoint: str) -> None:
                watcher = _DirSizeWatcher(
                    dest,
                    emit,
                    model_id=mid,
                    index=index,
                    model_count=total,
                    size_hint_bytes=hint_bytes,
                    endpoint=active_endpoint,
                )
                watcher.start()
                try:
                    ignore = _hub_ignore_patterns_for(spec)
                    snapshot_download(
                        repo_id=spec.hub_id,
                        local_dir=str(dest),
                        force_download=bool(force),
                        endpoint=active_endpoint or None,
                        # Fewer parallel streams is more stable on flaky domestic CDNs.
                        max_workers=4,
                        ignore_patterns=ignore,
                    )
                finally:
                    watcher.stop()

            def _run_with_connectivity_retries(active_endpoint: str, *, attempts: int) -> None:
                last_err: BaseException | None = None
                for attempt in range(max(1, attempts)):
                    try:
                        _run_snapshot(active_endpoint)
                        return
                    except Exception as err:
                        last_err = err
                        if not _is_hub_connectivity_error(err) or attempt + 1 >= attempts:
                            raise
                        wait_s = 2 * (attempt + 1)
                        emit(
                            {
                                "type": "progress",
                                "stage": "download",
                                "modelId": mid,
                                "index": index + 1,
                                "total": total,
                                "percent": int(100 * index / max(total, 1)),
                                "detail": (
                                    f"网络中断/超时，{wait_s}s 后重试 "
                                    f"{mid}（{attempt + 2}/{attempts}）…"
                                ),
                                "endpoint": active_endpoint or "https://huggingface.co",
                            }
                        )
                        time.sleep(wait_s)
                if last_err:
                    raise last_err

            try:
                # Official Hub: one try then mirror fallback. Mirror: multi-try with resume.
                first_attempts = (
                    CONNECTIVITY_RETRY_ATTEMPTS
                    if _endpoint_is_mirror(endpoint or "")
                    else 1
                )
                _run_with_connectivity_retries(endpoint, attempts=first_attempts)
            except Exception as first_err:
                # Official Hub is often unreachable in CN; one automatic mirror retry.
                using = (endpoint or "https://huggingface.co").rstrip("/")
                mirror = DEFAULT_HF_MIRROR.rstrip("/")
                if using != mirror and _is_hub_connectivity_error(first_err):
                    emit(
                        {
                            "type": "progress",
                            "stage": "download",
                            "modelId": mid,
                            "index": index + 1,
                            "total": total,
                            "percent": int(100 * index / max(total, 1)),
                            "detail": f"官方 Hub 不可达，改用镜像 {mirror} 重试 {mid}…",
                            "endpoint": mirror,
                        }
                    )
                    endpoint = apply_hf_endpoint(mirror)
                    _run_with_connectivity_retries(endpoint, attempts=CONNECTIVITY_RETRY_ATTEMPTS)
                else:
                    raise

            if not is_model_installed(mid):
                raise RuntimeError(
                    f"下载 {mid} 后仍缺少模型权重文件（可能是镜像未同步 LFS）。"
                    f"请换官方 Hub 或稍后重试。目录: {dest}"
                )
            final_bytes = _dir_nbytes(dest)
            results.append({"id": mid, "ok": True, "path": str(dest)})
            emit(
                {
                    "type": "progress",
                    "stage": "download",
                    "modelId": mid,
                    "index": index + 1,
                    "total": total,
                    "percent": int(100 * (index + 1) / max(total, 1)),
                    "downloadedBytes": final_bytes,
                    "totalBytes": final_bytes or hint_bytes or None,
                    "bytesPerSecond": 0,
                    "detail": f"已安装 {mid}",
                }
            )
        except Exception as err:
            # Stub / offline: create a marker so flows can proceed in TRANSUB_ENGINE_STUB
            from .paths import is_stub_mode

            if is_stub_mode():
                dest.mkdir(parents=True, exist_ok=True)
                (dest / "config.json").write_text('{"stub": true}\n', encoding="utf-8")
                results.append({"id": mid, "ok": True, "path": str(dest), "stub": True})
                continue

            friendly = format_hub_download_error(
                err,
                model_id=mid,
                endpoint=endpoint,
                hub_id=str(getattr(spec, "hub_id", "") or ""),
            )
            errors.append({"id": mid, "ok": False, "error": friendly})
            results.append({"id": mid, "ok": False, "error": friendly})
            emit(
                {
                    "type": "error",
                    "code": "DOWNLOAD_FAILED",
                    "message": friendly,
                    "modelId": mid,
                }
            )
            # Continue remaining models so one bad hub_id does not abort the batch.

    ok = len(errors) == 0
    done: dict[str, Any] = {
        "type": "done",
        "ok": ok,
        "results": results,
        "endpoint": endpoint or "https://huggingface.co",
    }
    if errors:
        done["errors"] = errors
        done["message"] = "；".join(e["error"] for e in errors if e.get("error"))
    emit(done)
    if not ok:
        raise RuntimeError(done["message"] or "model download failed")
    return done
